import{_ as a,c as o,o as r,ae as t}from"./chunks/framework.CHDT0Kbg.js";const p=JSON.parse('{"title":"Privacy and your data","description":"","frontmatter":{},"headers":[],"relativePath":"guide/privacy.md","filePath":"guide/privacy.md","lastUpdated":1795170900000}'),i={name:"guide/privacy.md"};function s(n,e,d,l,c,u){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="privacy-and-your-data" tabindex="-1">Privacy and your data <a class="header-anchor" href="#privacy-and-your-data" aria-label="Permalink to &quot;Privacy and your data&quot;">​</a></h1><p>What stays on your Mac, and what needs the network.</p><h2 id="stored-on-your-mac" tabindex="-1">Stored on your Mac <a class="header-anchor" href="#stored-on-your-mac" aria-label="Permalink to &quot;Stored on your Mac&quot;">​</a></h2><p>Your history, bookmarks, open tabs, downloads and cookies are saved locally. There is no account and no cloud sync. A private window (⌘⇧N) doesn&#39;t add to your history or session.</p><h2 id="when-the-network-is-used" tabindex="-1">When the network is used <a class="header-anchor" href="#when-the-network-is-used" aria-label="Permalink to &quot;When the network is used&quot;">​</a></h2><ul><li>Loading the websites you visit, of course.</li><li>Refreshing an ad-blocking subscription, when one is enabled. If the update fails, the saved rules keep working.</li><li>Downloading a user script or a file you asked for.</li></ul><h2 id="your-permissions" tabindex="-1">Your permissions <a class="header-anchor" href="#your-permissions" aria-label="Permalink to &quot;Your permissions&quot;">​</a></h2><p>Camera and microphone access is remembered per site, so you can allow one site and refuse another. Location and notifications are controlled by macOS itself. Pop-ups are limited to sites you allow.</p><h2 id="files-on-disk" tabindex="-1">Files on disk <a class="header-anchor" href="#files-on-disk" aria-label="Permalink to &quot;Files on disk&quot;">​</a></h2><p>Persim only reads files you choose in the system file dialog or explicitly grant access to. You can review and revoke those grants in Settings.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>Questions about privacy: <strong><a href="mailto:persim@w3cub.com" target="_blank" rel="noreferrer">persim@w3cub.com</a></strong>.</p>',12)])])}const y=a(i,[["render",s]]);export{p as __pageData,y as default};
